use std::fs

fn digit_val(c: char) -> int {
    let digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    let mut i = 0
    for d in digits.chars() {
        if d == c {
            return i
        }
        i += 1
    }
    0
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    let table = digits.chars().collect::<Vec<char>>()
    for line in text.lines() {
        let parts = line.split_whitespace().map(|p| p.to_string()).collect::<Vec<string>>()
        if parts.len() < 3 {
            continue
        }
        let from = parts[1].parse::<int>().unwrap_or(10)
        let to = parts[2].parse::<int>().unwrap_or(10)
        let mut n = 0
        for c in parts[0].chars() {
            n = n * from + digit_val(c)
        }
        if n == 0 {
            println("0")
            continue
        }
        let mut out: Vec<char> = []
        while n > 0 {
            out.push(table[n % to])
            n = n / to
        }
        let mut s = ""
        let mut k = out.len()
        while k > 0 {
            k -= 1
            s = s + out[k].to_string()
        }
        println(s)
    }
}

